5: /// 系统通知代理只记录实际的系统通知对象，不把注册请求当作送达。
6: final class LocalTaskNotificationService: NSObject, MobileTaskNotificationProtocol, UNUserNotificationCenterDelegate, @unchecked Sendable {
7:     private let worker: LocalTaskNotificationWorker
8: 
9:     init(center: UNUserNotificationCenter = .current()) {
10:         worker = LocalTaskNotificationWorker(center: center)
11:         super.init()
12:         center.delegate = self
13:     }
14: 
15:     func activate(accountID: String) async -> UUID { await worker.activate(accountID: accountID) }
16:     func permission() async -> MobileNotificationPermission { await worker.permission() }
17:     func requestPermission() async throws -> MobileNotificationPermission { try await worker.requestPermission() }
18:     func reconcile(tasks: [MobileTask], accountID: String, sessionToken: UUID) async -> MobileTaskNotificationSnapshot {
19:         await worker.reconcile(tasks: tasks, accountID: accountID, sessionToken: sessionToken)
20:     }
21:     func observations(accountID: String, sessionToken: UUID) async -> [MobileTaskObservation] {
22:         await worker.observations(accountID: accountID, sessionToken: sessionToken)
23:     }
24:     func acknowledge(eventID: String) async { await worker.acknowledge(eventID: eventID) }
25:     func remove(taskID: String, accountID: String, sessionToken: UUID, includeDelivered: Bool) async {
