45: /// 所有系统请求写入串行执行。会话令牌在网络读取前取得，退出清理会使旧读取失效。
46: private actor LocalTaskNotificationWorker {
47:     private let center: UNUserNotificationCenter
48:     private let managedPrefix = "recordagent.task."
49:     private var accountPrefix: String?
50:     private var sessionToken: UUID?
51:     private var observed: [String: MobileTaskObservation] = [:]
52:     private var mutationLocked = false
53:     private var mutationWaiters: [CheckedContinuation<Void, Never>] = []
54: 
55:     init(center: UNUserNotificationCenter) { self.center = center }
56: 
57:     func activate(accountID: String) async -> UUID {
58:         guard !Task.isCancelled else { return UUID() }
59:         await acquireMutation()
60:         defer { releaseMutation() }
61:         guard !Task.isCancelled else { return UUID() }
62:         let prefix = Self.prefix(accountID: accountID)
63:         let token = UUID()
64:         accountPrefix = prefix
65:         observed = observed.filter { $0.value.eventID.hasPrefix(prefix) }
66:         // 同账户重建页面也开启新生命周期，旧模型尚未返回的配置不得再写系统通知。
67:         sessionToken = REDACTED
68:         await removeAllManaged(except: prefix)
69:         return token
70:     }
71: 
72:     func permission() async -> MobileNotificationPermission {
73:         let settings = await center.notificationSettings()
74:         switch settings.authorizationStatus {
75:         case .authorized: return .authorized
76:         case .provisional, .ephemeral: return .provisional
77:         case .denied: return .denied
78:         case .notDetermined: return .notDetermined
79:         @unknown default: return .denied
80:         }
81:     }
82: 
83:     func requestPermission() async throws -> MobileNotificationPermission {
84:         if await permission() == .notDetermined {
85:             _ = try await center.requestAuthorization(options: [.alert, .sound, .badge])
86:         }
87:         return await permission()
88:     }
89: 
90:     func reconcile(tasks: [MobileTask], accountID: String, sessionToken token: UUID) async -> MobileTaskNotificationSnapshot {
91:         await acquireMutation()
92:         defer { releaseMutation() }
93:         let permission = await permission()
94:         var result = MobileTaskNotificationSnapshot(permission: permission, registrations: [:])
95:         let prefix = Self.prefix(accountID: accountID)
96:         guard accountPrefix == prefix, sessionToken == token, !Task.isCancelled else { return result }
97:         let pending = await center.pendingNotificationRequests()
98:         let enabled = Array(tasks.filter(\.enabled).prefix(32))
99:         let expected = Set(enabled.compactMap { task in
100:             MobileTaskSchedule.nextDate(for: task) == nil ? nil : Self.identifier(accountID: accountID, taskID: task.id)
101:         })
102:         let stale = pending.filter { $0.identifier.hasPrefix(managedPrefix) &&
103:             (!permission.canRegister || !expected.contains($0.identifier)) }.map(\.identifier)
104:         center.removePendingNotificationRequests(withIdentifiers: stale)
105:         let unmanagedCount = pending.filter { !$0.identifier.hasPrefix(managedPrefix) }.count
106:         let capacity = max(0, 64 - unmanagedCount)
107:         var added = 0
108:         for task in enabled {
109:             guard !Task.isCancelled else { break }
110:             guard MobileTaskSchedule.nextDate(for: task) != nil else {
111:                 result.registrations[task.id] = .expired
112:                 continue
113:             }
114:             guard permission.canRegister else {
115:                 result.registrations[task.id] = permission == .denied ? .permissionDenied : .permissionRequired
116:                 continue
117:             }
118:             guard added < capacity, let parts = try? MobileTaskSchedule.components(for: task) else {
119:                 center.removePendingNotificationRequests(withIdentifiers: [Self.identifier(accountID: accountID, taskID: task.id)])
120:                 result.registrations[task.id] = .failed
121:                 continue
122:             }
123:             let content = UNMutableNotificationContent()
124:             content.title = task.title
125:             content.body = task.body
126:             content.sound = .default
127:             let identifier = Self.identifier(accountID: accountID, taskID: task.id)
128:             let request = UNNotificationRequest(identifier: identifier, content: content,
129:                 trigger: UNCalendarNotificationTrigger(dateMatching: parts, repeats: task.recurrence != .once))
130:             do {
131:                 // 相同 identifier 替换旧请求，编辑时间、时区和内容不会叠加通知。
132:                 try await center.add(request)
133:                 result.registrations[task.id] = .registered
134:                 added += 1
135:             } catch {
136:                 center.removePendingNotificationRequests(withIdentifiers: [identifier])
137:                 result.registrations[task.id] = .failed
138:             }
139:         }
140:         for task in tasks where !task.enabled { result.registrations[task.id] = .paused }
141:         return result
142:     }
143: 
144:     func observations(accountID: String, sessionToken token: UUID) async -> [MobileTaskObservation] {
145:         let prefix = Self.prefix(accountID: accountID)
146:         guard accountPrefix == prefix, sessionToken == token else { return [] }
147:         let delivered = await center.deliveredNotifications()
148:         guard accountPrefix == prefix, sessionToken == token else { return [] }
149:         for notification in delivered {
150:             if let observation = Self.observation(notification, prefix: prefix) {
151:                 observed[observation.eventID] = observation
152:             }
153:         }
154:         return observed.values.filter { $0.eventID.hasPrefix(prefix) }.sorted { $0.deliveredAt < $1.deliveredAt }
155:     }
156: 
157:     func remember(_ notification: UNNotification) {
158:         let identifier = notification.request.identifier
159:         let pieces = identifier.split(separator: ".")
160:         guard pieces.count == 4, identifier.hasPrefix(managedPrefix), pieces[2].count == 32 else { return }
161:         let prefix = accountPrefix ?? "recordagent.task.\(pieces[2])."
162:         // 冷启动点击先保留真实系统证据；登录后只上传与已核验账户摘要匹配的观察。
163:         guard let observation = Self.observation(notification, prefix: prefix) else { return }
164:         observed[observation.eventID] = observation
165:         if observed.count > 64, let oldest = observed.values.min(by: { $0.deliveredAt < $1.deliveredAt }) {
166:             observed[oldest.eventID] = nil
167:         }
168:     }
169: 
170:     func acknowledge(eventID: String) { observed[eventID] = nil }
171: 
172:     func remove(taskID: String, accountID: String, sessionToken token: UUID, includeDelivered: Bool) async {
173:         await acquireMutation()
174:         defer { releaseMutation() }
175:         guard accountPrefix == Self.prefix(accountID: accountID), sessionToken == token else { return }
176:         let identifier = Self.identifier(accountID: accountID, taskID: taskID)
177:         center.removePendingNotificationRequests(withIdentifiers: [identifier])
178:         if includeDelivered {
179:             center.removeDeliveredNotifications(withIdentifiers: [identifier])
180:             observed = observed.filter { $0.value.taskID.lowercased() != taskID.lowercased() }
181:         }
182:     }
183: 
184:     func clearAll() async {
185:         await acquireMutation()
186:         defer { releaseMutation() }
187:         sessionToken = nil
188:         accountPrefix = nil
189:         observed.removeAll()
190:         await removeAllManaged()
191:     }
192: 
193:     private func removeAllManaged(except keptPrefix: String? = nil) async {
194:         let pending = await center.pendingNotificationRequests()
195:         center.removePendingNotificationRequests(withIdentifiers: pending.filter {
196:             $0.identifier.hasPrefix(managedPrefix) && !(keptPrefix.map($0.identifier.hasPrefix) ?? false)
197:         }.map(\.identifier))
198:         let delivered = await center.deliveredNotifications()
199:         center.removeDeliveredNotifications(withIdentifiers: delivered.filter {
200:             $0.request.identifier.hasPrefix(managedPrefix) && !(keptPrefix.map($0.request.identifier.hasPrefix) ?? false)

