193:     private func openEventStream<Body: Encodable & Sendable>(
194:         path: String,
195:         payload: Body
196:     ) -> AsyncThrowingStream<AgentStreamEvent, Error> {
197:         AsyncThrowingStream { continuation in
198:             let task = Task {
199:                 do {
200:                     let body = try APIClient.encoder.encode(payload)
201:                     let bytes = try await client.openStreamBytes(path, method: "POST", body: body)
202:                     var parser = SSELineParser()
203:                     var reachedTerminal = false
204: 
205:                     for try await byte in bytes {
206:                         try Task.checkCancellation()
207:                         if let event = parser.feed(byte) {
208:                             continuation.yield(event)
209:                             if Self.isTerminal(event) {
210:                                 reachedTerminal = true
211:                                 break
212:                             }
213:                         }
214:                     }
215: 
216:                     if !reachedTerminal, let trailing = parser.finish() {
217:                         continuation.yield(trailing)
218:                         if Self.isTerminal(trailing) {
219:                             reachedTerminal = true
220:                         }
221:                     }
222: 
223:                     if !reachedTerminal {
224:                         continuation.yield(.error(String(localized: "agent.error.unexpected_eof")))
225:                     }
226:                     continuation.finish()
227:                 } catch is CancellationError {
228:                     continuation.finish(throwing: CancellationError())
229:                 } catch {
230:                     continuation.finish(throwing: error)
231:                 }
232:             }
233:             continuation.onTermination = { _ in
234:                 task.cancel()
235:             }
236:         }
237:     }
