239:     private static func isTerminal(_ event: AgentStreamEvent) -> Bool {
240:         switch event {
241:         case .done, .cancelled, .error, .permissionRequired:
242:             return true
243:         case .runStarted, .text, .thinking, .toolCall, .toolResult, .subagent, .routingNotice:
244:             return false
245:         }
246:     }
