18: /** 远程单用户 API 令牌边界；本地开发模式可保持兼容，远程部署必须显式要求令牌。 */
19: @Component
20: @Order(Ordered.HIGHEST_PRECEDENCE + 1)
21: public class ApiTokenFilter extends OncePerRequestFilter {
22: 
23:     @Value("${butvan.api.access-token:}")
24:     private String configuredToken;
25: 
26:     @Value("${butvan.api.require-token:false}")
27:     private boolean requireToken;
28: 
29:     /** 强制模式下拒绝空令牌配置，避免误以为服务器已受保护。 */
30:     @PostConstruct
31:     public void validateConfiguration() {
32:         if (requireToken && (configuredToken == null || configuredToken.trim().length() < 32)) {
33:             throw new IllegalStateException("BUTVAN_API_REQUIRE_TOKEN=true 时必须配置至少 32 个字符的 BUTVAN_API_TOKEN");
34:         }
35:     }
36: 
37:     @Override
38:     protected boolean shouldNotFilter(HttpServletRequest request) {
39:         String path = request.getRequestURI();
40:         return "OPTIONS".equalsIgnoreCase(request.getMethod())
41:                 || !(path.startsWith("/agent/") || path.startsWith("/api/"));
42:     }
43: 
44:     @Override
45:     protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
46:             throws ServletException, IOException {
47:         String expected = configuredToken == null ? "" : configuredToken.trim();
48:         if (expected.isEmpty() && !requireToken) {
49:             chain.doFilter(request, response);
50:             return;
51:         }
52: 
53:         String presented = bearerToken(request);
54:         if (presented == null && isNativeResourceRequest(request)) {
55:             // EventSource 和原生 img/download 不能设置 Authorization 头，只允许这些只读 GET 使用查询令牌。
56:             presented = request.getParameter("access_token");
57:         }
58:         if (presented == null || !MessageDigest.isEqual(
59:                 expected.getBytes(StandardCharsets.UTF_8), presented.getBytes(StandardCharsets.UTF_8))) {
60:             response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
61:             response.setContentType("application/json;charset=UTF-8");
62:             response.getWriter().write("{\"code\":401,\"message\":\"API Token 无效或缺失\",\"data\":null}");
63:             return;
64:         }
65:         chain.doFilter(request, response);
66:     }
67: 
68:     private String bearerToken(HttpServletRequest request) {
69:         String authorization = request.getHeader("Authorization");
70:         if (authorization == null || !authorization.regionMatches(true, 0, "Bearer ", 0, 7)) return null;
71:         return authorization.substring(7).trim();
72:     }
73: 
74:     private boolean isNativeResourceRequest(HttpServletRequest request) {
75:         if (!"GET".equalsIgnoreCase(request.getMethod())) return false;
76:         String path = request.getRequestURI();
77:         return path.equals("/agent/automations/stream")
78:                 || path.equals("/agent/study-sessions/stream")
79:                 || path.equals("/api/tasks/stream")
80:                 || path.equals("/agent/account/avatar/content")
81:                 || (path.startsWith("/agent/records/") && path.contains("/attachments/") && path.endsWith("/content"));
82:     }
83: }

