44:         synchronized (monitor) {
45:             if (closing) {
46:                 emitter.complete();
47:                 return emitter;
48:             }
49:             subscribers.computeIfAbsent(ownerId, ignored -> ConcurrentHashMap.newKeySet()).add(emitter);
50:             if (!send(ownerId, emitter, "snapshot", initialSnapshot)) {
