4: struct SSELineParser {
5:     private var lineBuffer: [UInt8] = []
6:     private var currentEventName: String?
7:     private var dataLines: [String] = []
8:     private let decoder: JSONDecoder
9: 
10:     init(decoder: JSONDecoder = APIClient.decoder) {
11:         self.decoder = decoder
12:     }
13: 
14:     mutating func feed(_ byte: UInt8) -> AgentStreamEvent? {
15:         if byte == 0x0A { // '\n'
16:             if lineBuffer.last == 0x0D { // '\r'
17:                 lineBuffer.removeLast()
18:             }
19:             let line = String(decoding: lineBuffer, as: UTF8.self)
20:             lineBuffer.removeAll(keepingCapacity: true)
21:             return processLine(line)
22:         }
23:         lineBuffer.append(byte)
24:         return nil
25:     }
26: 
27:     mutating func finish() -> AgentStreamEvent? {
28:         if !lineBuffer.isEmpty {
29:             if lineBuffer.last == 0x0D {
30:                 lineBuffer.removeLast()
31:             }
32:             let line = String(decoding: lineBuffer, as: UTF8.self)
33:             lineBuffer.removeAll(keepingCapacity: false)
34:             if let event = processLine(line) {
35:                 return event
36:             }
37:         }
38:         return flushEvent()
39:     }
40: 
41:     private mutating func processLine(_ line: String) -> AgentStreamEvent? {
42:         if line.isEmpty {
43:             return flushEvent()
44:         }
45:         if line.hasPrefix(":") {
46:             return nil
47:         }
48:         if line.hasPrefix("event:") {
49:             let value = line.dropFirst(6).trimmingCharacters(in: .whitespaces)
50:             currentEventName = value.isEmpty ? nil : value
51:             return nil
52:         }
53:         if line.hasPrefix("data:") {
54:             dataLines.append(String(line.dropFirst(5)))
55:             return nil
56:         }
57:         return nil
58:     }
59: 
60:     private mutating func flushEvent() -> AgentStreamEvent? {
61:         guard currentEventName != nil || !dataLines.isEmpty else {
62:             return nil
63:         }
