package butvan.agent.network.push;

import com.fasterxml.jackson.annotation.JsonProperty;

import java.time.Instant;
import java.util.List;

/**
 * iOS 主动推送、设备登记与 APNs 凭据的持久化领域模型。
 */
public final class IosPushModels {
    private IosPushModels() {}

    /** 主动推送大类，对应 iOS 端设置页三个独立开关。 */
    public enum PushCategory {
        COMPANION,
        SIGNAL,
        AUTOMATION
    }

    /** APNs 投递环境。 */
    public enum ApnsEnvironment {
        SANDBOX,
        PRODUCTION;

        public static ApnsEnvironment parse(String raw) {
            if (raw != null && "production".equalsIgnoreCase(raw.strip())) {
                return PRODUCTION;
            }
            return SANDBOX;
        }

        public String wireValue() {
            return this == PRODUCTION ? "production" : "sandbox";
        }
    }

    /** APNs 服务端推送配置；私钥只允许写入，永不序列化到接口响应或日志。 */
    public record ApnsConfig(
            boolean enabled,
            String teamId,
            String keyId,
            String bundleId,
            @JsonProperty(access = JsonProperty.Access.WRITE_ONLY) String privateKeyPem,
            boolean sandbox
    ) {
        public ApnsConfig {
            teamId = teamId == null ? "" : teamId.strip();
            keyId = keyId == null ? "" : keyId.strip();
            bundleId = (bundleId == null || bundleId.isBlank()) ? "com.butvan.recordagent" : bundleId.strip();
            privateKeyPem = privateKeyPem == null ? "" : privateKeyPem.strip();
        }

        public static ApnsConfig defaults() {
            return new ApnsConfig(false, "", "", "com.butvan.recordagent", "", true);
        }

        public boolean configured() {
            return !teamId.isBlank() && !keyId.isBlank() && !bundleId.isBlank() && !privateKeyPem.isBlank();
        }

        @Override
        public String toString() {
            return "ApnsConfig{enabled=" + enabled + ", teamId='" + teamId + "', keyId='" + keyId
                    + "', bundleId='" + bundleId + "', sandbox=" + sandbox + ", configured=" + configured() + "}";
        }
    }

    /** 单台 iOS 设备登记与推送偏好（即使免费签名暂无 APNs Token，也保留设备 ID 与类别偏好）。 */
    public record DeviceRegistration(
            String ownerId,
            String deviceId,
            String deviceToken,
            ApnsEnvironment environment,
            String appVersion,
            boolean companionPushEnabled,
            boolean signalPushEnabled,
            boolean automationPushEnabled,
            Instant updatedAt
    ) {
        public DeviceRegistration {
            ownerId = ownerId == null ? "" : ownerId.strip();
            deviceId = deviceId == null ? "" : deviceId.strip();
            deviceToken = normalizeToken(deviceToken);
            environment = environment == null ? ApnsEnvironment.SANDBOX : environment;
            appVersion = appVersion == null ? "" : appVersion.strip();
        }

        public boolean allows(PushCategory category) {
            return switch (category) {
                case COMPANION -> companionPushEnabled;
                case SIGNAL -> signalPushEnabled;
                case AUTOMATION -> automationPushEnabled;
            };
        }

        public boolean hasApnsToken() {
            return !deviceToken.isBlank();
        }

        public static String normalizeToken(String raw) {
            if (raw == null) return "";
            String cleaned = raw.replaceAll("[^0-9a-fA-F]", "").toLowerCase();
            return cleaned;
        }

        @Override
        public String toString() {
            return "DeviceRegistration{deviceId='" + deviceId + "', hasToken=" + hasApnsToken()
                    + ", environment=" + environment + "}";
        }
    }

    /** 面向 iOS 前台 SSE / 补拉与 APNs 的统一主动通知条目。 */
    public record IosNotice(
            String id,
            String ownerId,
            PushCategory category,
            String kind,
            String title,
            String body,
            String sessionId,
            String routeTarget,
            Instant createdAt,
            boolean acknowledged,
            String apnsStatus
    ) {
        public IosNotice {
            ownerId = ownerId == null ? "" : ownerId.strip();
            category = category == null ? PushCategory.COMPANION : category;
            kind = kind == null ? "" : kind.strip();
            title = (title == null || title.isBlank()) ? "RecordAgent 提醒" : title.strip();
            body = body == null ? "" : body.strip();
            sessionId = sessionId == null ? "" : sessionId.strip();
            routeTarget = (routeTarget == null || routeTarget.isBlank()) ? "chat" : routeTarget.strip();
            apnsStatus = apnsStatus == null ? "NOT_CONFIGURED" : apnsStatus.strip();
        }

        public IosNotice withAcknowledged(boolean ack) {
            return new IosNotice(id, ownerId, category, kind, title, body, sessionId, routeTarget,
                    createdAt, ack, apnsStatus);
        }

        public IosNotice withApnsStatus(String nextStatus) {
            return new IosNotice(id, ownerId, category, kind, title, body, sessionId, routeTarget,
                    createdAt, acknowledged, nextStatus);
        }
    }

    /** `~/.butvan-agent/ios-push.json` 完整持久化文件结构。 */
    public record PushState(
            ApnsConfig apnsConfig,
            List<DeviceRegistration> devices,
            List<IosNotice> notices
    ) {
        public PushState {
            apnsConfig = apnsConfig == null ? ApnsConfig.defaults() : apnsConfig;
            devices = devices == null ? List.of() : List.copyOf(devices);
            notices = notices == null ? List.of() : List.copyOf(notices);
        }

        public static PushState defaults() {
            return new PushState(ApnsConfig.defaults(), List.of(), List.of());
        }
    }
}

package butvan.agent.network.push;

import butvan.agent.network.push.IosPushModels.*;

import java.time.Instant;
import java.util.List;

/**
 * iOS 主动推送 HTTP / SSE 接口传输 DTO（脱敏，绝不回传 APNs 私钥或完整 Device Token）。
 */
public final class IosPushDtos {
    private IosPushDtos() {}

    /** 设备摘要信息。 */
    public record DeviceSummary(
            String deviceId,
            boolean hasApnsToken,
            String tokenPrefix,
            String environment,
            String appVersion,
            boolean companionPushEnabled,
            boolean signalPushEnabled,
            boolean automationPushEnabled,
            Instant updatedAt
    ) {
        public static DeviceSummary from(DeviceRegistration d) {
            String token = d.deviceToken();
            String prefix = token.length() >= 8 ? token.substring(0, 8) + "…" : (token.isEmpty() ? "" : token);
            return new DeviceSummary(
                    d.deviceId(),
                    d.hasApnsToken(),
                    prefix,
                    d.environment().wireValue(),
                    d.appVersion(),
                    d.companionPushEnabled(),
                    d.signalPushEnabled(),
                    d.automationPushEnabled(),
                    d.updatedAt()
            );
        }
    }

    /** 单条主动通知响应 DTO。 */
    public record IosNoticeResponse(
            String id,
            String category,
            String kind,
            String title,
            String body,
            String sessionId,
            String routeTarget,
            Instant createdAt,
            boolean acknowledged,
            String apnsStatus
    ) {
        public static IosNoticeResponse from(IosNotice n) {
            return new IosNoticeResponse(
                    n.id(),
                    n.category().name(),
                    n.kind(),
                    n.title(),
                    n.body(),
                    n.sessionId(),
                    n.routeTarget(),
                    n.createdAt(),
                    n.acknowledged(),
                    n.apnsStatus()
            );
        }
    }

    /** 当前用户的 iOS 推送总览状态与实时流快照。 */
    public record IosPushStatusResponse(
            boolean apnsConfigured,
            boolean apnsEnabled,
            boolean sandbox,
            String teamId,
            String keyId,
            String bundleId,
            int registeredDeviceCount,
            int apnsTokenDeviceCount,
            int unacknowledgedCount,
            List<DeviceSummary> devices,
            List<IosNoticeResponse> pendingNotices
    ) {}

    /** iOS 端注册或更新设备及推送偏好请求。 */
    public record RegisterDeviceRequest(
            String deviceId,
            String deviceToken,
            String environment,
            String appVersion,
            Boolean companionPushEnabled,
            Boolean signalPushEnabled,
            Boolean automationPushEnabled
    ) {}

    /** 服务端 APNs 凭据配置请求（privateKeyPem 留空保留旧值）。 */
    public record SaveApnsConfigRequest(
            Boolean enabled,
            String teamId,
            String keyId,
            String bundleId,
            String privateKeyPem,
            Boolean sandbox
    ) {}

    /** 测试推送请求。 */
    public record TestPushRequest(
            String title,
            String body,
            String category
    ) {}

    /** 测试推送响应。 */
    public record TestPushResponse(
            IosNoticeResponse notice,
            int attemptedDevices,
            int apnsSentCount,
            String apnsSummary
    ) {}
}

package butvan.agent.network.push;

import butvan.agent.agents.storage.AgentStorageProperties;
import butvan.agent.network.push.IosPushModels.*;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.attribute.PosixFilePermission;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;

/**
 * 将 iOS 推送配置、设备登记与最近通知列表原子保存至 `~/.butvan-agent/ios-push.json`（0600 权限）。
 */
@Slf4j
@Component
@RequiredArgsConstructor
public class IosPushStore {
    private static final int MAX_NOTICES = 50;
    private static final int MAX_DEVICES = 16;
    private static final long MAX_FILE_BYTES = 2_000_000L;

    private final AgentStorageProperties storageProperties;
    private final ObjectMapper objectMapper = new ObjectMapper()
            .findAndRegisterModules()
            .configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);

    public synchronized PushState load() {
        Path file = storageProperties.getIosPushFile();
        if (file == null || !Files.exists(file) || Files.isSymbolicLink(file) || !Files.isRegularFile(file)) {
            return PushState.defaults();
        }
        try {
            if (Files.size(file) > MAX_FILE_BYTES) {
                log.warn("iOS 推送状态文件超过上限，使用默认状态");
                return PushState.defaults();
            }
            String raw = Files.readString(file, StandardCharsets.UTF_8);
            if (raw == null || raw.isBlank()) {
                return PushState.defaults();
            }
            PushState parsed = objectMapper.readValue(raw, PushState.class);
            return parsed == null ? PushState.defaults() : parsed;
        } catch (IOException e) {
            log.warn("读取 iOS 推送状态文件失败：{}", e.getClass().getSimpleName());
            return PushState.defaults();
        }
    }

    public synchronized PushState save(PushState state) {
        Path target = storageProperties.getIosPushFile();
        try {
            Path parent = target.getParent();
            if (parent != null) {
                if (Files.isSymbolicLink(parent)) {
                    throw new IllegalStateException("iOS 推送配置目录不能是符号链接");
                }
                Files.createDirectories(parent);
            }
            if (Files.isSymbolicLink(target)) {
                throw new IllegalStateException("iOS 推送配置文件不能是符号链接");
            }
            Path temp = Files.createTempFile(parent, ".ios-push-", ".tmp");
            try {
                // 使用显式反序列化友好的 writer（注意：ApnsConfig.privateKeyPem 在 record 上标注了 WRITE_ONLY，
                // 文件持久化需要完整保存私钥，因此使用单独的持久化视图写入）。
                String json = objectMapper.writerWithDefaultPrettyPrinter()
                        .writeValueAsString(PersistedPushState.from(state));
                Files.writeString(temp, json, StandardCharsets.UTF_8);
                restrictOwnerOnly(temp);
                try {
                    Files.move(temp, target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
                } catch (AtomicMoveNotSupportedException ignored) {
                    Files.move(temp, target, StandardCopyOption.REPLACE_EXISTING);
                }
                restrictOwnerOnly(target);
            } finally {
                Files.deleteIfExists(temp);
            }
            return state;
        } catch (IOException e) {
            throw new IllegalStateException("保存 iOS 推送状态失败", e);
        }
    }

    public synchronized PushState upsertDevice(DeviceRegistration registration) {
        PushState current = load();
        List<DeviceRegistration> next = new ArrayList<>();
        next.add(registration);
        for (DeviceRegistration existing : current.devices()) {
            if (existing.ownerId().equals(registration.ownerId()) && existing.deviceId().equals(registration.deviceId())) {
                continue;
            }
            // 同一个非空 APNs Token 迁移到新 deviceId 时，清理旧绑定避免重复弹窗。
            if (registration.hasApnsToken() && existing.hasApnsToken()
                    && existing.deviceToken().equals(registration.deviceToken())) {
                continue;
            }
            if (next.size() < MAX_DEVICES) {
                next.add(existing);
            }
        }
        return save(new PushState(current.apnsConfig(), next, current.notices()));
    }

    public synchronized PushState removeDevice(String ownerId, String deviceId) {
        PushState current = load();
        List<DeviceRegistration> next = current.devices().stream()
                .filter(d -> !(d.ownerId().equals(ownerId) && d.deviceId().equals(deviceId)))
                .toList();
        return save(new PushState(current.apnsConfig(), next, current.notices()));
    }

    public synchronized PushState removeInvalidToken(String deviceToken) {
        String normalized = DeviceRegistration.normalizeToken(deviceToken);
        if (normalized.isBlank()) return load();
        PushState current = load();
        List<DeviceRegistration> next = current.devices().stream()
                .map(d -> normalized.equals(d.deviceToken())
                        ? new DeviceRegistration(d.ownerId(), d.deviceId(), "", d.environment(), d.appVersion(),
                                d.companionPushEnabled(), d.signalPushEnabled(), d.automationPushEnabled(), d.updatedAt())
                        : d)
                .toList();
        return save(new PushState(current.apnsConfig(), next, current.notices()));
    }

    public synchronized PushState appendNotice(IosNotice notice) {
        PushState current = load();
        List<IosNotice> next = new ArrayList<>(current.notices().size() + 1);
        next.add(notice);
        for (IosNotice existing : current.notices()) {
            if (!existing.id().equals(notice.id()) && next.size() < MAX_NOTICES) {
                next.add(existing);
            }
        }
        return save(new PushState(current.apnsConfig(), current.devices(), next));
    }

    public synchronized PushState updateNoticeApnsStatus(String ownerId, String noticeId, String apnsStatus) {
        PushState current = load();
        List<IosNotice> next = current.notices().stream()
                .map(n -> (n.ownerId().equals(ownerId) && n.id().equals(noticeId))
                        ? n.withApnsStatus(apnsStatus)
                        : n)
                .toList();
        return save(new PushState(current.apnsConfig(), current.devices(), next));
    }

    public synchronized PushState acknowledgeNotice(String ownerId, String noticeId) {
        PushState current = load();
        List<IosNotice> next = current.notices().stream()
                .map(n -> (n.ownerId().equals(ownerId) && n.id().equals(noticeId))
                        ? n.withAcknowledged(true)
                        : n)
                .toList();
        return save(new PushState(current.apnsConfig(), current.devices(), next));
    }

    public synchronized PushState clearNoticesForOwner(String ownerId) {
        PushState current = load();
        List<IosNotice> next = current.notices().stream()
                .filter(n -> !n.ownerId().equals(ownerId))
                .toList();
        return save(new PushState(current.apnsConfig(), current.devices(), next));
    }

    private void restrictOwnerOnly(Path path) {
        try {
            Set<PosixFilePermission> perms = EnumSet.of(
                    PosixFilePermission.OWNER_READ,
                    PosixFilePermission.OWNER_WRITE
            );
            Files.setPosixFilePermissions(path, perms);
        } catch (UnsupportedOperationException | IOException ignored) {
            // 非 POSIX 文件系统（如 Windows）忽略 POSIX 权限设置。
        }
    }

    /** 专用于本地文件序列化，避免 ApnsConfig 上的 WRITE_ONLY 丢弃私钥。 */
    private record PersistedApnsConfig(
            boolean enabled,
            String teamId,
            String keyId,
            String bundleId,
            String privateKeyPem,
            boolean sandbox
    ) {}

    private record PersistedPushState(
            PersistedApnsConfig apnsConfig,
            List<DeviceRegistration> devices,
            List<IosNotice> notices
    ) {
        private static PersistedPushState from(PushState state) {
            ApnsConfig cfg = state.apnsConfig();
            return new PersistedPushState(
                    new PersistedApnsConfig(cfg.enabled(), cfg.teamId(), cfg.keyId(), cfg.bundleId(),
                            cfg.privateKeyPem(), cfg.sandbox()),
                    state.devices(),
                    state.notices()
            );
        }
    }
}

package butvan.agent.network.push;

import butvan.agent.network.push.IosPushModels.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.security.KeyFactory;
import java.security.PrivateKey;
import java.security.Signature;
import java.security.spec.PKCS8EncodedKeySpec;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.Base64;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * 零外部依赖的 Apple APNs HTTP/2 客户端（使用 Java 21 原生 HttpClient 与 ECDSA P-256 ES256 签名）。
 */
@Slf4j
@Component
public class ApnsClient {
    private static final String SANDBOX_HOST = "https://api.sandbox.push.apple.com";
    private static final String PRODUCTION_HOST = "https://api.push.apple.com";
    private static final Duration TOKEN_TTL = Duration.ofMinutes(45);
    private static final Duration REQUEST_TIMEOUT = Duration.ofSeconds(8);

    private final HttpClient httpClient;
    private final ObjectMapper objectMapper;
    private final Clock clock;
    private final Map<String, CachedJwt> jwtCache = new ConcurrentHashMap<>();

    public ApnsClient() {
        this(
                HttpClient.newBuilder()
                        .version(HttpClient.Version.HTTP_2)
                        .connectTimeout(Duration.ofSeconds(5))
                        .build(),
                new ObjectMapper().findAndRegisterModules(),
                Clock.systemUTC()
        );
    }

    ApnsClient(HttpClient httpClient, ObjectMapper objectMapper, Clock clock) {
        this.httpClient = httpClient;
        this.objectMapper = objectMapper;
        this.clock = clock;
    }

    public record DeliveryOutcome(boolean success, boolean invalidToken, int statusCode, String summary) {}

    /** 向指定 iOS 设备推送一条告警通知，绝不记录或回显私钥与完整设备令牌。 */
    public DeliveryOutcome send(ApnsConfig config, DeviceRegistration device, IosNotice notice) {
        if (config == null || !config.enabled() || !config.configured()) {
            return new DeliveryOutcome(false, false, 0, "APNs 未启用或凭据不完整");
        }
        if (device == null || !device.hasApnsToken()) {
            return new DeliveryOutcome(false, false, 0, "设备缺少 APNs Token");
        }
        try {
            String jwt = resolveJwt(config);
            String host = resolveHost(config, device);
            URI uri = URI.create(host + "/3/device/" + device.deviceToken());
            String payload = buildPayload(notice);

            HttpRequest request = HttpRequest.newBuilder(uri)
                    .timeout(REQUEST_TIMEOUT)
                    .header("authorization", "bearer " + jwt)
                    .header("apns-topic", config.bundleId())
                    .header("apns-push-type", "alert")
                    .header("apns-priority", "10")
                    .header("apns-collapse-id", notice.id())
                    .header("content-type", "application/json")
                    .POST(HttpRequest.BodyPublishers.ofString(payload, StandardCharsets.UTF_8))
                    .build();

            HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
            int status = response.statusCode();
            if (status == 200) {
                return new DeliveryOutcome(true, false, 200, "SENT");
            }
            String reason = extractReason(response.body());
            boolean invalid = status == 410
                    || (status == 400 && ("BadDeviceToken".equals(reason) || "DeviceTokenNotForTopic".equals(reason)));
            log.warn("APNs 推送未成功：status={}, reason={}, deviceId={}", status, reason, device.deviceId());
            return new DeliveryOutcome(false, invalid, status, reason.isBlank() ? "HTTP_" + status : reason);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return new DeliveryOutcome(false, false, 0, "INTERRUPTED");
        } catch (Exception e) {
            log.warn("APNs 推送异常：type={}, deviceId={}", e.getClass().getSimpleName(), device.deviceId());
            return new DeliveryOutcome(false, false, 0, e.getClass().getSimpleName());
        }
    }

    /** 生成符合 Apple APNs 规范的 ES256 Provider Authentication JWT（供测试与内部复用）。 */
    String generateJwt(ApnsConfig config, Instant issuedAt) throws Exception {
        String headerJson = objectMapper.writeValueAsString(Map.of("alg", "ES256", "kid", config.keyId()));
        String claimsJson = objectMapper.writeValueAsString(Map.of(
                "iss", config.teamId(),
                "iat", issuedAt.getEpochSecond()
        ));
        Base64.Encoder urlEncoder = Base64.getUrlEncoder().withoutPadding();
        String unsigned = urlEncoder.encodeToString(headerJson.getBytes(StandardCharsets.UTF_8))
                + "."
                + urlEncoder.encodeToString(claimsJson.getBytes(StandardCharsets.UTF_8));

        PrivateKey privateKey = REDACTED;
        Signature signer = Signature.getInstance("SHA256withECDSAinP1363Format");
        signer.initSign(privateKey);
        signer.update(unsigned.getBytes(StandardCharsets.UTF_8));
        byte[] rawSignature = signer.sign();
        return unsigned + "." + urlEncoder.encodeToString(rawSignature);
    }

    String buildPayload(IosNotice notice) throws Exception {
        Map<String, Object> alert = new LinkedHashMap<>();
        alert.put("title", truncate(notice.title(), 80));
        alert.put("body", truncate(notice.body(), 240));

        Map<String, Object> aps = new LinkedHashMap<>();
        aps.put("alert", alert);
        aps.put("sound", "default");
        aps.put("interruption-level", "active");

        Map<String, Object> meta = new LinkedHashMap<>();
        meta.put("noticeId", notice.id());
        meta.put("category", notice.category().name());
        meta.put("kind", notice.kind());
        meta.put("sessionId", notice.sessionId());
        meta.put("routeTarget", notice.routeTarget());

        Map<String, Object> root = new LinkedHashMap<>();
        root.put("aps", aps);
        root.put("recordAgent", meta);
        return objectMapper.writeValueAsString(root);
    }

    private String resolveJwt(ApnsConfig config) throws Exception {
        String cacheKey = config.teamId() + "|" + config.keyId() + "|" + config.privateKeyPem().hashCode();
        Instant now = clock.instant();
        CachedJwt cached = jwtCache.get(cacheKey);
        if (cached != null && now.isBefore(cached.issuedAt().plus(TOKEN_TTL))) {
            return cached.token();
        }
        String fresh = generateJwt(config, now);
        jwtCache.put(cacheKey, new CachedJwt(fresh, now));
        return fresh;
    }

    private String resolveHost(ApnsConfig config, DeviceRegistration device) {
        if (device.environment() == ApnsEnvironment.PRODUCTION && !config.sandbox()) {
            return PRODUCTION_HOST;
        }
        return SANDBOX_HOST;
    }

    private PrivateKey parseEcPrivateKey(String pem) throws Exception {
        String normalized = pem
                .replace("-----BEGIN PRIVATE KEY-----", "")
                .replace("-----END PRIVATE KEY-----", "")
                .replaceAll("\\s+", "");
        byte[] keyBytes = Base64.getDecoder().decode(normalized);
        PKCS8EncodedKeySpec spec = new PKCS8EncodedKeySpec(keyBytes);
        return KeyFactory.getInstance("EC").generatePrivate(spec);
    }

    private String extractReason(String body) {
        if (body == null || body.isBlank()) return "";
        try {
            var node = objectMapper.readTree(body);
            var reasonNode = node.get("reason");
            return reasonNode == null ? "" : reasonNode.asText("");
        } catch (Exception ignored) {
            return "";
        }
    }

    private static String truncate(String text, int max) {
        if (text == null) return "";
        String trimmed = text.strip();
        return trimmed.length() <= max ? trimmed : trimmed.substring(0, max - 1) + "…";
    }

    private record CachedJwt(String token, Instant issuedAt) {}
}

package butvan.agent.network.push;

import butvan.agent.network.push.IosPushDtos.IosPushStatusResponse;
import lombok.extern.slf4j.Slf4j;
import org.springframework.context.event.ContextClosedEvent;
import org.springframework.context.event.EventListener;
import org.springframework.stereotype.Service;
import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

/**
 * iOS 前台与恢复态订阅主动通知实时流（SSE，替代客户端高频轮询）。
 */
@Slf4j
@Service
public class IosPushStreamService {
    private final ConcurrentMap<String, Set<SseEmitter>> subscribers = new ConcurrentHashMap<>();
    private final Object monitor = new Object();
    private final ScheduledExecutorService heartbeat = Executors.newSingleThreadScheduledExecutor(r -> {
        Thread t = new Thread(r, "ios-push-sse-heartbeat");
        t.setDaemon(true);
        return t;
    });
    private boolean closing;

    public IosPushStreamService() {
        heartbeat.scheduleWithFixedDelay(this::sendHeartbeats, 25, 25, TimeUnit.SECONDS);
    }

    public SseEmitter subscribe(String ownerId, IosPushStatusResponse initialSnapshot) {
        SseEmitter emitter = new SseEmitter(0L);
        emitter.onCompletion(() -> unsubscribe(ownerId, emitter));
        emitter.onTimeout(() -> unsubscribe(ownerId, emitter));
        emitter.onError(ignored -> unsubscribe(ownerId, emitter));
        synchronized (monitor) {
            if (closing) {
                emitter.complete();
                return emitter;
            }
            subscribers.computeIfAbsent(ownerId, ignored -> ConcurrentHashMap.newKeySet()).add(emitter);
            if (!send(ownerId, emitter, "snapshot", initialSnapshot)) {
                return emitter;
            }
        }
        return emitter;
    }

    public void publish(String ownerId, IosPushStatusResponse snapshot) {
        if (ownerId == null || snapshot == null) return;
        synchronized (monitor) {
            if (closing) return;
            Set<SseEmitter> ownerSubscribers = subscribers.get(ownerId);
            if (ownerSubscribers == null || ownerSubscribers.isEmpty()) return;
            for (SseEmitter emitter : new ArrayList<>(ownerSubscribers)) {
                send(ownerId, emitter, "updated", snapshot);
            }
        }
    }

    @EventListener(ContextClosedEvent.class)
    public void close() {
        heartbeat.shutdownNow();
        List<SseEmitter> emitters;
        synchronized (monitor) {
            closing = true;
            emitters = subscribers.values().stream().flatMap(Set::stream).toList();
            subscribers.clear();
        }
        emitters.forEach(SseEmitter::complete);
    }

    private boolean send(String ownerId, SseEmitter emitter, String eventName, IosPushStatusResponse payload) {
        try {
            emitter.send(SseEmitter.event().name(eventName).data(payload));
            return true;
        } catch (IOException | IllegalStateException exception) {
            log.debug("iOS 主动推送 SSE 客户端已断开：ownerId={}", ownerId);
            unsubscribe(ownerId, emitter);
            emitter.complete();
            return false;
        }
    }

    private void sendHeartbeats() {
        synchronized (monitor) {
            if (closing || subscribers.isEmpty()) return;
            for (var entry : subscribers.entrySet()) {
                for (SseEmitter emitter : new ArrayList<>(entry.getValue())) {
                    try {
                        emitter.send(SseEmitter.event().name("heartbeat").data("ping"));
                    } catch (IOException | IllegalStateException ignored) {
                        unsubscribe(entry.getKey(), emitter);
                        emitter.complete();
                    }
                }
            }
        }
    }

    private void unsubscribe(String ownerId, SseEmitter emitter) {
        Set<SseEmitter> ownerSubscribers = subscribers.get(ownerId);
        if (ownerSubscribers == null) return;
        ownerSubscribers.remove(emitter);
        if (ownerSubscribers.isEmpty()) {
            subscribers.remove(ownerId, ownerSubscribers);
        }
    }
}

package butvan.agent.network.push;

import butvan.agent.agents.reset.ResetBarrier;
import butvan.agent.network.push.IosPushDtos.*;
import butvan.agent.network.push.IosPushModels.*;
import jakarta.annotation.PreDestroy;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;

import java.time.Clock;
import java.time.Instant;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * 统一协调 iOS 设备登记、前台 SSE 实时提醒、APNs 远程弹窗与三类主动事件投递。
 */
@Slf4j
@Service
public class IosPushService {
    private final IosPushStore store;
    private final ApnsClient apnsClient;
    private final IosPushStreamService streamService;
    private final Clock clock;
    private final ResetBarrier resetBarrier;
    private final ApnsConfig envFallbackApns;
    private final ExecutorService apnsExecutor = Executors.newSingleThreadExecutor(r -> {
        Thread t = new Thread(r, "ios-push-apns");
        t.setDaemon(true);
        return t;
    });

    @Autowired
    public IosPushService(
            IosPushStore store,
            ApnsClient apnsClient,
            IosPushStreamService streamService,
            Clock automationClock,
            @Autowired(required = false) ResetBarrier resetBarrier,
            @Value("${butvan.push.apns.enabled:false}") boolean envEnabled,
            @Value("${butvan.push.apns.team-id:}") String envTeamId,
            @Value("${butvan.push.apns.key-id:}") String envKeyId,
            @Value("${butvan.push.apns.bundle-id:com.butvan.recordagent}") String envBundleId,
            @Value("${butvan.push.apns.private-key:}") String envPrivateKey,
            @Value("${butvan.push.apns.sandbox:true}") boolean envSandbox
    ) {
        this.store = store;
        this.apnsClient = apnsClient;
        this.streamService = streamService;
        this.clock = automationClock == null ? Clock.systemUTC() : automationClock;
        this.resetBarrier = resetBarrier;
        this.envFallbackApns = new ApnsConfig(envEnabled, envTeamId, envKeyId, envBundleId, envPrivateKey, envSandbox);
    }

    public SseEmitter subscribe(String ownerId) {
        return streamService.subscribe(ownerId, status(ownerId));
    }

    public IosPushStatusResponse status(String ownerId) {
        PushState state = store.load();
        ApnsConfig apns = effectiveApnsConfig(state);
        List<DeviceRegistration> ownerDevices = state.devices().stream()
                .filter(d -> d.ownerId().equals(ownerId))
                .toList();
        List<IosNoticeResponse> pending = state.notices().stream()
                .filter(n -> n.ownerId().equals(ownerId) && !n.acknowledged())
                .map(IosNoticeResponse::from)
                .toList();
        int tokenCount = (int) ownerDevices.stream().filter(DeviceRegistration::hasApnsToken).count();
        return new IosPushStatusResponse(
                apns.configured(),
                apns.enabled(),
                apns.sandbox(),
                apns.teamId(),
                apns.keyId(),
                apns.bundleId(),
                ownerDevices.size(),
                tokenCount,
                pending.size(),
                ownerDevices.stream().map(DeviceSummary::from).toList(),
                pending
        );
    }

    public IosPushStatusResponse registerDevice(String ownerId, RegisterDeviceRequest req) {
        if (req == null || req.deviceId() == null || req.deviceId().isBlank()) {
            throw new IllegalArgumentException("设备标识不能为空");
        }
        String deviceId = req.deviceId().strip();
        if (deviceId.length() > 128) {
            throw new IllegalArgumentException("设备标识长度超限");
        }
        PushState current = store.load();
        DeviceRegistration existing = current.devices().stream()
                .filter(d -> d.ownerId().equals(ownerId) && d.deviceId().equals(deviceId))
                .findFirst()
                .orElse(null);

        String resolvedToken = req.deviceToken() != null
                ? DeviceRegistration.normalizeToken(req.deviceToken())
                : (existing == null ? "" : existing.deviceToken());
        ApnsEnvironment env = req.environment() != null
                ? ApnsEnvironment.parse(req.environment())
                : (existing == null ? ApnsEnvironment.SANDBOX : existing.environment());
        String appVersion = req.appVersion() != null
                ? req.appVersion().strip()
                : (existing == null ? "" : existing.appVersion());
        boolean companionEnabled = req.companionPushEnabled() != null
                ? req.companionPushEnabled()
                : (existing == null || existing.companionPushEnabled());
        boolean signalEnabled = req.signalPushEnabled() != null
                ? req.signalPushEnabled()
                : (existing == null || existing.signalPushEnabled());
        boolean automationEnabled = req.automationPushEnabled() != null
                ? req.automationPushEnabled()
                : (existing == null || existing.automationPushEnabled());

        DeviceRegistration registration = new DeviceRegistration(
                ownerId, deviceId, resolvedToken, env, appVersion,
                companionEnabled, signalEnabled, automationEnabled, clock.instant()
        );
        store.upsertDevice(registration);
        IosPushStatusResponse snapshot = status(ownerId);
        streamService.publish(ownerId, snapshot);
        return snapshot;
    }

    public IosPushStatusResponse removeDevice(String ownerId, String deviceId) {
        if (deviceId != null && !deviceId.isBlank()) {
            store.removeDevice(ownerId, deviceId.strip());
        }
        IosPushStatusResponse snapshot = status(ownerId);
        streamService.publish(ownerId, snapshot);
        return snapshot;
    }

    public IosPushStatusResponse saveApnsConfig(String ownerId, SaveApnsConfigRequest req) {
        if (req == null) throw new IllegalArgumentException("APNs 配置不能为空");
        PushState current = store.load();
        ApnsConfig prev = current.apnsConfig();
        String nextPem = (req.privateKeyPem() == null || req.privateKeyPem().isBlank())
                ? prev.privateKeyPem()
                : req.privateKeyPem().strip();
        ApnsConfig next = new ApnsConfig(
                req.enabled() != null ? req.enabled() : prev.enabled(),
                req.teamId() != null ? req.teamId() : prev.teamId(),
                req.keyId() != null ? req.keyId() : prev.keyId(),
                req.bundleId() != null ? req.bundleId() : prev.bundleId(),
                nextPem,
                req.sandbox() != null ? req.sandbox() : prev.sandbox()
        );
        if (next.enabled() && !next.configured()) {
            throw new IllegalArgumentException("启用 APNs 推送前请先填全 Team ID、Key ID、Bundle ID 与 .p8 私钥");
        }
        store.save(new PushState(next, current.devices(), current.notices()));
        IosPushStatusResponse snapshot = status(ownerId);
        streamService.publish(ownerId, snapshot);
        return snapshot;
    }

    public List<IosNoticeResponse> notices(String ownerId, boolean includeAcknowledged) {
        return store.load().notices().stream()
                .filter(n -> n.ownerId().equals(ownerId) && (includeAcknowledged || !n.acknowledged()))
                .map(IosNoticeResponse::from)
                .toList();
    }

    public IosPushStatusResponse acknowledgeNotice(String ownerId, String noticeId) {
        if (noticeId != null && !noticeId.isBlank()) {
            store.acknowledgeNotice(ownerId, noticeId.strip());
        }
        IosPushStatusResponse snapshot = status(ownerId);
        streamService.publish(ownerId, snapshot);
        return snapshot;
    }

    /**
     * 统一向 iOS 端发布主动通知：
     * 1) 始终写入待送达通知流并通过 SSE 实时触达前台设备；
     * 2) 若服务端 APNs 已配置且设备已登记 Token，则异步通过 HTTP/2 APNs 发出离屏系统弹窗。
     */
    public IosNotice publishNotice(
            String ownerId,
            PushCategory category,
            String kind,
            String title,
            String body,
            String sessionId,
            String routeTarget
    ) {
        if (ownerId == null || ownerId.isBlank() || body == null || body.isBlank()) return null;
        if (resetBarrier != null && resetBarrier.blocked()) return null;
        long generation = resetBarrier == null ? -1 : resetBarrier.state().generation();

        PushState state = store.load();
        List<DeviceRegistration> ownerDevices = state.devices().stream()
                .filter(d -> d.ownerId().equals(ownerId))
                .toList();
        // 若用户至少登记了一台设备，且所有设备均关闭了该类通知，则直接跳过，不打扰用户。
        if (!ownerDevices.isEmpty() && ownerDevices.stream().noneMatch(d -> d.allows(category))) {
            return null;
        }

        ApnsConfig apns = effectiveApnsConfig(state);
        List<DeviceRegistration> apnsTargets = ownerDevices.stream()
                .filter(d -> d.allows(category) && d.hasApnsToken())
                .toList();

        String initialApnsStatus = (!apns.enabled() || !apns.configured())
                ? "NOT_CONFIGURED"
                : (apnsTargets.isEmpty() ? "NO_DEVICE" : "PENDING");

        IosNotice notice = new IosNotice(
                UUID.randomUUID().toString(),
                ownerId,
                category,
                kind,
                title,
                body,
                sessionId,
                routeTarget,
                clock.instant(),
                false,
                initialApnsStatus
        );
        store.appendNotice(notice);
        streamService.publish(ownerId, status(ownerId));

        if ("PENDING".equals(initialApnsStatus)) {
            apnsExecutor.submit(() -> deliverApnsBatch(ownerId, generation, apns, apnsTargets, notice));
        }
        return notice;
    }

    /** 手动发送一条测试推送，同步返回 APNs 实际投递结果摘要。 */
    public TestPushResponse sendTestNotice(String ownerId, TestPushRequest req) {
        PushCategory category = parseCategory(req == null ? null : req.category());
        String title = (req == null || req.title() == null || req.title().isBlank())
                ? "RecordAgent 主动提醒测试"
                : req.title().strip();
        String body = (req == null || req.body() == null || req.body().isBlank())
                ? "这是一条主动推送测试消息，点击可直达对话。"
                : req.body().strip();

        PushState state = store.load();
        ApnsConfig apns = effectiveApnsConfig(state);
        List<DeviceRegistration> targets = state.devices().stream()
                .filter(d -> d.ownerId().equals(ownerId) && d.hasApnsToken())
                .toList();

        IosNotice notice = new IosNotice(
                UUID.randomUUID().toString(),
                ownerId,
                category,
                "PUSH_TEST",
                title,
                body,
                "",
                category == PushCategory.AUTOMATION ? "tasks" : "chat",
                clock.instant(),
                false,
                (!apns.enabled() || !apns.configured()) ? "NOT_CONFIGURED" : (targets.isEmpty() ? "NO_DEVICE" : "PENDING")
        );
        store.appendNotice(notice);
        streamService.publish(ownerId, status(ownerId));

        int sent = 0;
        String summary;
        if (!apns.enabled() || !apns.configured()) {
            summary = "APNs 未在服务端启用或凭据未配置，已推送至前台 SSE 与回前台待拉队列";
        } else if (targets.isEmpty()) {
            summary = "尚无已登记 APNs Token 的设备，已推送至前台 SSE 与回前台待拉队列";
        } else {
            ApnsResultSummary result = executeApnsBatch(ownerId, apns, targets, notice);
            sent = result.sentCount();
            notice = notice.withApnsStatus(result.status());
            summary = result.summary();
        }
        return new TestPushResponse(IosNoticeResponse.from(notice), targets.size(), sent, summary);
    }

    @PreDestroy
    public void shutdown() {
        apnsExecutor.shutdownNow();
    }

    private void deliverApnsBatch(
            String ownerId,
            long expectedGeneration,
            ApnsConfig apns,
            List<DeviceRegistration> targets,
            IosNotice notice
    ) {
        if (resetBarrier != null && (resetBarrier.blocked() || !resetBarrier.isCurrent(expectedGeneration))) {
            store.updateNoticeApnsStatus(ownerId, notice.id(), "SKIPPED");
            return;
        }
        executeApnsBatch(ownerId, apns, targets, notice);
    }

    private ApnsResultSummary executeApnsBatch(
            String ownerId,
            ApnsConfig apns,
            List<DeviceRegistration> targets,
            IosNotice notice
    ) {
        int sent = 0;
        String lastFailure = "";
        for (DeviceRegistration device : targets) {
            ApnsClient.DeliveryOutcome outcome = apnsClient.send(apns, device, notice);
            if (outcome.success()) {
                sent++;
            } else {
                lastFailure = outcome.summary();
                if (outcome.invalidToken()) {
                    store.removeInvalidToken(device.deviceToken());
                }
            }
        }
        String finalStatus = sent > 0 ? "SENT" : "FAILED";
        store.updateNoticeApnsStatus(ownerId, notice.id(), finalStatus);
        streamService.publish(ownerId, status(ownerId));
        String summary = sent > 0
                ? "APNs 已发送至 " + sent + "/" + targets.size() + " 台设备"
                : "APNs 发送未成功：" + (lastFailure.isBlank() ? "UNKNOWN" : lastFailure);
        return new ApnsResultSummary(sent, finalStatus, summary);
    }

    private ApnsConfig effectiveApnsConfig(PushState state) {
        ApnsConfig stored = state.apnsConfig();
        if (stored != null && stored.configured()) {
            return stored;
        }
        return envFallbackApns.configured() ? envFallbackApns : (stored == null ? ApnsConfig.defaults() : stored);
    }

    private static PushCategory parseCategory(String raw) {
        if (raw == null || raw.isBlank()) return PushCategory.COMPANION;
        try {
            return PushCategory.valueOf(raw.strip().toUpperCase());
        } catch (IllegalArgumentException ignored) {
            return PushCategory.COMPANION;
        }
    }

    private record ApnsResultSummary(int sentCount, String status, String summary) {}
}

